#!/usr/bin/env python3
"""Render the native read-only inspection export; never construct graph semantics."""
import json
import sys
from pathlib import Path

view = json.loads(Path(sys.argv[1]).read_text())
assert view['schema'] == 'native-vm-growth-view-v1'
ids = {n['id'] for n in view['nodes']}
assert all(e['source'] in ids and e['target'] in ids for e in view['edges'])
assert all(len(n['address']) == 64 for n in view['nodes'])
assert len(ids) == len(view['nodes'])
controllers = sum(n['registry'] == 'member-registry-v1' and n['label'] in (':CONTROLLER', ':STEP-CONTROLLER') for n in view['nodes'])
region_label = 'coordination region' if controllers > 1 else 'run region'
data = json.dumps(view).replace('<', '\\u003c')
html = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Native VM growth · addressed SHG</title>
<style>*{box-sizing:border-box}body{margin:0;background:#0e151c;color:#e3edf5;font:14px system-ui}header{padding:20px 24px;border-bottom:1px solid #334454}h1{font-size:22px;margin:0 0 8px}small{color:#a6bdcd}nav{padding:12px 24px;display:flex;gap:12px;align-items:center;border-bottom:1px solid #334454}button,select,input{padding:8px;background:#21303d;color:#e3edf5;border:1px solid #496477;border-radius:5px}main{display:grid;grid-template-columns:minmax(0,1fr) 390px;height:calc(100vh - 160px)}canvas{width:100%;height:100%;touch-action:none;background:radial-gradient(ellipse,#172332,#0e151c 75%)}aside{padding:20px;overflow:auto;border-left:1px solid #334454}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px ui-monospace;line-height:1.5}#address{color:#70d3b4;overflow-wrap:anywhere}h2{font-size:17px}.chip{display:inline-block;border:1px solid #496477;border-radius:4px;padding:5px;margin:5px 0}#counts{color:#a6bdcd}@media(max-width:850px){main{grid-template-columns:1fr;height:auto}canvas{height:65vh}}</style>
<header><h1>Native VM growth · addressed SHG</h1><small>Original 13 functions / 19 CALLs preserved. __CONTROLLERS__ controller definition(s) grown through native construction; CALL seed authored.</small></header>
<nav><select id="view"><option value="web">Calls and coordination web</option><option value="all">All addressed rows</option></select><input id="search" placeholder="Find name, role or address"><label><input id="expand" type="checkbox" checked> Expand child</label><button id="fit">Fit</button><button id="headers">Native snapshots</button><span id="counts"></span></nav>
<main><canvas id="network" aria-label="Native VM call and coordination hypergraph; select nodes, drag to pan, scroll to zoom"></canvas><aside><h2 id="title">Native incidence web</h2><div id="address"></div><p>Blue: original VM members. Green: grown child members. Purple diamonds: native relations. Small cyan nodes: typed ports. Amber: parent/child boundary correspondence.</p><div class="chip">Structural candidate</div><div class="chip">Behavioral / liveness proof OPEN</div><pre id="detail">Select a member to inspect its native row and H002 address. Lines represent native incidences and H006 correspondences. Amber lines cross the child boundary; click any line for its witness. These links do not imply execution order.</pre><details><summary>Native correspondence witness</summary><pre id="witness"></pre></details></aside></main>
<script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),C=document.getElementById('network'),ctx=C.getContext('2d');
let nodes=[],edges=[],w=0,h=0,scale=1,tx=0,ty=0,drag=null,picked=null;
const R='relation-registry-v1',M='member-registry-v1',P='port-registry-v1';
function build(){const all=document.getElementById('view').value==='all',used=new Set(D.edges.flatMap(e=>[e.source,e.target]));nodes=D.nodes.filter(n=>(n.scope!=='child'||document.getElementById('expand').checked)&&(all||n.registry===M||n.registry===R||(n.registry===P&&used.has(n.id)))).map((m,i)=>({m,x:(m.scope==='parent'?-250:250)+210*Math.cos(i*2.399),y:210*Math.sin(i*2.399)}));const map=new Map(nodes.map(n=>[n.m.id,n]));edges=D.edges.filter(e=>map.has(e.source)&&map.has(e.target));
for(let t=0;t<240;t++){const forces=nodes.map(()=>[0,0]);for(let i=0;i<nodes.length;i++){for(let j=i+1;j<nodes.length;j++){let dx=nodes[i].x-nodes[j].x,dy=nodes[i].y-nodes[j].y,d2=dx*dx+dy*dy+80,k=1200/d2;forces[i][0]+=dx*k;forces[i][1]+=dy*k;forces[j][0]-=dx*k;forces[j][1]-=dy*k;}forces[i][0]+=( (nodes[i].m.scope==='parent'?-250:250)-nodes[i].x)*.006;forces[i][1]+=-nodes[i].y*.006;}for(const e of edges){const a=map.get(e.source),b=map.get(e.target),i=nodes.indexOf(a),j=nodes.indexOf(b),dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy)||1,k=(d-110)*.018/d;forces[i][0]+=dx*k;forces[i][1]+=dy*k;forces[j][0]-=dx*k;forces[j][1]-=dy*k;}nodes.forEach((n,i)=>{n.x+=Math.max(-8,Math.min(8,forces[i][0]));n.y+=Math.max(-8,Math.min(8,forces[i][1]));});}document.getElementById('counts').textContent=`${nodes.length} rows · ${edges.filter(e=>!e.type).length} incidences + ${edges.filter(e=>e.type).length} boundary links · ${D.resolved_addresses} native addresses resolved`;fit();}
function fit(){if(!nodes.length)return;const xs=nodes.map(n=>n.x),ys=nodes.map(n=>n.y),x0=Math.min(...xs)-80,x1=Math.max(...xs)+180,y0=Math.min(...ys)-120,y1=Math.max(...ys)+120;scale=Math.min(w/(x1-x0),h/(y1-y0),1.3);tx=(w-(x0+x1)*scale)/2;ty=(h-(y0+y1)*scale)/2;draw();}
function draw(){ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);ctx.clearRect(0,0,w,h);ctx.translate(tx,ty);ctx.scale(scale,scale);const child=nodes.filter(n=>n.m.scope==='child');if(child.length){const x0=Math.min(...child.map(n=>n.x))-45,x1=Math.max(...child.map(n=>n.x))+80,y0=Math.min(...child.map(n=>n.y))-50,y1=Math.max(...child.map(n=>n.y))+40;ctx.fillStyle='rgba(80,180,150,.035)';ctx.fillRect(x0,y0,x1-x0,y1-y0);ctx.strokeStyle='#467e70';ctx.setLineDash([8/scale,5/scale]);ctx.strokeRect(x0,y0,x1-x0,y1-y0);ctx.setLineDash([]);ctx.font=(12/scale)+'px system-ui';ctx.fillStyle='#80dabf';ctx.fillText('Embedded __REGION__ · native H006 child',x0+12/scale,y0+20/scale);}const map=new Map(nodes.map(n=>[n.m.id,n])),q=document.getElementById('search').value.toLowerCase();for(const e of edges){const a=map.get(e.source),b=map.get(e.target);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=e.type==='boundary-correspondence'?'#ffcb75':e.type?'#80dabf':e.role==='phase'||e.role==='transition'?'#bc8fd3':'#6f98af';ctx.globalAlpha=e.type?.9:.45;ctx.lineWidth=(e.type?2:1)/scale;ctx.stroke();if(scale>.8){ctx.globalAlpha=.7;ctx.fillStyle='#a6bdcd';ctx.font=(10/scale)+'px system-ui';ctx.fillText(e.role,(a.x+b.x)/2,(a.y+b.y)/2);}}ctx.globalAlpha=1;for(const n of nodes){ctx.globalAlpha=!q||JSON.stringify(n.m).toLowerCase().includes(q)?1:.12;ctx.beginPath();if(n.m.registry===R){ctx.moveTo(n.x,n.y-7/scale);ctx.lineTo(n.x+7/scale,n.y);ctx.lineTo(n.x,n.y+7/scale);ctx.lineTo(n.x-7/scale,n.y);ctx.closePath();}else ctx.arc(n.x,n.y,(n.m.registry===P?4:7)/scale,0,Math.PI*2);ctx.fillStyle=n.m.registry===R?'#ca95f0':n.m.registry===P?'#70d3d7':n.m.registry===M?(n.m.scope==='parent'?'#82b8ff':'#80dabf'):'#a6aab2';ctx.fill();if(picked===n.m.id){ctx.lineWidth=3/scale;ctx.strokeStyle='#fff';ctx.stroke();}ctx.fillStyle='#dfedf7';ctx.font=(11/scale)+'px system-ui';let label=n.m.label.replace(/"[a-f0-9]{64}"\s*/g,'');if(n.m.registry===M&&n.m.details.includes(':MEMBER-KIND :CHILD-BUNDLE'))label='embedded __REGION__';if(label.length>44)label=label.slice(-40);ctx.fillText(label,n.x+14,n.y+4);}ctx.globalAlpha=1;}
function inspectEdge(e){picked=null;document.getElementById('title').textContent=e.role;document.getElementById('address').textContent=e.correspondence?'H006 correspondence: '+e.correspondence:'Native incidence: '+e.incidence;const {details,...summary}=e;document.getElementById('detail').textContent=JSON.stringify(summary,null,2);document.getElementById('witness').textContent=details||'';draw();}
function inspect(n){document.getElementById('witness').textContent='';picked=n.id;document.getElementById('title').textContent=n.label;document.getElementById('address').textContent=n.address;document.getElementById('detail').textContent=`scope: ${n.scope}\nregistry: ${n.registry}\nrow: ${n.id}\n\n${n.details}`;draw();}
C.onpointerdown=e=>{C.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,tx,ty,moved:false};};C.onpointermove=e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>3)drag.moved=true;tx=drag.tx+e.clientX-drag.x;ty=drag.ty+e.clientY-drag.y;draw();};C.onpointerup=e=>{if(drag&&!drag.moved){const r=C.getBoundingClientRect(),x=(e.clientX-r.left-tx)/scale,y=(e.clientY-r.top-ty)/scale,n=nodes.find(n=>Math.hypot(n.x-x,n.y-y)<18/scale);if(n)inspect(n.m);else{const map=new Map(nodes.map(n=>[n.m.id,n]));const edge=edges.find(e=>{const a=map.get(e.source),b=map.get(e.target),dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((x-a.x)*dx+(y-a.y)*dy)/(dx*dx+dy*dy||1)));return Math.hypot(x-a.x-t*dx,y-a.y-t*dy)<6/scale;});if(edge)inspectEdge(edge);}}drag=null;};C.onwheel=e=>{e.preventDefault();const r=C.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,s=Math.max(.05,Math.min(5,scale*Math.exp(-e.deltaY*.001)));tx=x-(x-tx)*s/scale;ty=y-(y-ty)*s/scale;scale=s;draw();};document.getElementById('fit').onclick=fit;document.getElementById('view').onchange=build;document.getElementById('expand').onchange=build;document.getElementById('search').oninput=draw;document.getElementById('headers').onclick=()=>{document.getElementById('title').textContent='Native bundle snapshots';document.getElementById('address').textContent='';document.getElementById('detail').textContent=JSON.stringify(D.headers,null,2);};new ResizeObserver(()=>{w=C.clientWidth;h=C.clientHeight;C.width=w*devicePixelRatio;C.height=h*devicePixelRatio;fit();}).observe(C);build();
</script></html>'''.replace('__DATA__', data).replace('__CONTROLLERS__', str(controllers)).replace('__REGION__', region_label)
Path(sys.argv[2]).write_text(html)
print(f"native graph rendered: {len(view['nodes'])} rows, {len(view['edges'])} links")
